const express = require('express');
const axios = require('axios');
const NodeCache = require('node-cache');

const app = express();
const responseCache = new NodeCache({ stdTTL: 300, checkperiod: 60 });

// Middleware to normalize and cache responses
app.use((req, res, next) => {
  // Cache key includes the Host header for multi-tenant support
  const cacheKey = `${req.headers.host}${req.path}`;
  const cached = responseCache.get(cacheKey);
  if (cached) {
    res.set('X-Cache', 'HIT');
    return res.status(cached.status).json(cached.body);
  }
  res.originalJson = res.json.bind(res);
  res.json = (body) => {
    responseCache.set(cacheKey, { status: res.statusCode, body });
    res.set('X-Cache', 'MISS');
    return res.originalJson(body);
  };
  next();
});

// Fetch instance metadata for health enrichment
async function getInstanceMetadata() {
  try {
    const tokenResp = await axios.put('http://169.254.169.254/latest/api/token', null, {
      headers: { 'X-aws-ec2-metadata-token-ttl-seconds': '21600' },
      timeout: 2000
    });
    const token = tokenResp.data;
    const metaResp = await axios.get('http://169.254.169.254/latest/meta-data/iam/security-credentials/', {
      headers: { 'X-aws-ec2-metadata-token': token },
      timeout: 2000
    });
    return metaResp.data;
  } catch (e) {
    return null;
  }
}

// Health endpoint that includes cloud metadata
app.get('/api/health', async (req, res) => {
  const metadata = await getInstanceMetadata();
  res.json({
    status: 'healthy',
    timestamp: Date.now(),
    instance: metadata || 'unavailable',
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// User profile endpoint - uses X-Forwarded-Host for cache keying
app.get('/api/profile/:id', async (req, res) => {
  const userId = req.params.id;
  // Simulate DB lookup
  const profile = {
    id: userId,
    name: `User ${userId}`,
    avatar: `https://${req.headers['x-forwarded-host'] || req.headers.host}/avatars/${userId}.png`,
    links: {
      self: `https://${req.headers['x-forwarded-host'] || req.headers.host}/api/profile/${userId}`
    }
  };
  res.json(profile);
});

// Configuration endpoint that reads from upstream
app.get('/api/config', async (req, res) => {
  try {
    const upstream = req.headers['x-upstream-config'] || 'http://config-service:8080/config';
    const configResp = await axios.get(upstream, { timeout: 3000 });
    res.json(configResp.data);
  } catch (e) {
    res.status(502).json({ error: 'config unavailable' });
  }
});

// Cache invalidation (admin only - checked at ingress layer)
app.post('/api/cache/flush', (req, res) => {
  responseCache.flushAll();
  res.json({ flushed: true });
});

app.listen(3000, () => {
  console.log('Service running on port 3000');
});

module.exports = app;
